   Marine(int x, int y, int default_damage);

   int attack();                       // 데미지를리턴한다.
   void be_attacked(int damage_earn);  // 입는데미지
   void move(int x, int y);            // 새로운위치

   void show_status();  // 상태를보여준다.

   ~Marine() { total_marine_num--; }
 };
