 // 숫자로된열번호를A, B, .... Z, AA, AB, ... 이런순으로매겨준다.
 string TxtTable::col_num_to_str(int n) {
   string s = "";
   if (n < 26) {
     s.push_back('A' + n);
   } else {
     char first = 'A' + n / 26 - 1;
     char second = 'A' + n % 26;

     s.push_back(first);
     s.push_back(second);
   }

   return s;
 }


