C++ 쓰레드                                                                                       761


 #include <mutex>
 #include <queue>
 #include <string>
 #include <thread>
 #include <vector>

 void producer(std::queue<std::string>* downloaded_pages, std::mutex* m,
               int index, std::condition_variable* cv) {
   for (int i = 0; i < 5; i++) {
     // 웹사이트를다운로드하는데걸리는시간이라생각하면된다.
     // 각쓰레드별로다운로드하는데걸리는시간이다르다.
     std::this_thread::sleep_for(std::chrono::milliseconds(100 * index));
     std::string content = "웹사이트: " + std::to_string(i) + " from thread(" +
                           std::to_string(index) + ")\n";

     // data 는쓰레드사이에서공유되므로critical section 에넣어야한다.
     m->lock();
     downloaded_pages->push(content);
     m->unlock();

     // consumer 에게content 가준비되었음을알린다.
     cv->notify_one();
   }
 }

 void consumer(std::queue<std::string>* downloaded_pages, std::mutex* m,
               int* num_processed, std::condition_variable* cv) {
   while (*num_processed < 25) {
     std::unique_lock<std::mutex> lk(*m);

     cv->wait(
         lk, [&] { return !downloaded_pages->empty() || *num_processed == 25; });

     if (*num_processed == 25) {
       lk.unlock();
       return;
     }

     // 맨앞의페이지를읽고대기목록에서제거한다.
     std::string content = downloaded_pages->front();
     downloaded_pages->pop();

     (*num_processed)++;
     lk.unlock();

     // content 를처리한다.
     std::cout << content;
     std::this_thread::sleep_for(std::chrono::milliseconds(80));
   }
 }

