 void worker(std::promise<string>* p) {
   // 약속을이행하는모습. 해당결과는future 에들어간다.
   p->set_value("some data");
 }
 int main() {
   std::promise<string> p;

   // 미래에string 데이터를돌려주겠다는약속.
   std::future<string> data = p.get_future();

   std::thread t(worker, &p);

   // 미래에약속된데이터를받을때까지기다린다.

