정리해보자면promise 는생산자-소비자패턴에서마치생산자(producer) 의역할을수행하고,
future 는소비자(consumer) 의역할을수행한다고보면됩니다.

따라서아래와같이조건변수를통해서도promise - future 패턴을구현할수있습니다.


 #include <condition_variable>
 #include <iostream>
 #include <mutex>
 #include <string>
 #include <thread>

 std::condition_variable cv;
 std::mutex m;
 bool done = false;
 std::string info;

 void worker() {
   {
     std::lock_guard<std::mutex> lk(m);
     info = "some data";  // 위의p->set_value("some data") 에대응
     done = true;
   }
   cv.notify_all();
 }

 int main() {
   std::thread t(worker);

   std::unique_lock<std::mutex> lk(m);
   cv.wait(lk, [] { return done; });  // 위의data.wait() 이라보면된다.
   lk.unlock();

   std::cout << "받은데이터: " << info << std::endl;

   t.join();

