 #include <exception>
 #include <future>
 #include <iostream>
 #include <string>
 #include <thread>
 using std::string;

 void worker(std::promise<string>* p) {
   try {
     throw std::runtime_error("Some Error!");
   } catch (...) {
     // set_exception 에는exception_ptr 를전달해야한다.
     p->set_exception(std::current_exception());
   }
