 int main() {
   std::promise<string> p;

   // 미래에string 데이터를돌려주겠다는약속.
   std::future<string> data = p.get_future();

   std::thread t(worker, &p);

   // 미래에약속된데이터를받을때까지기다린다.
   data.wait();

   try {
     data.get();
   } catch (const std::exception& e) {
     std::cout << "예외: " << e.what() << std::endl;
   }
   t.join();
 }



