std::async

앞서promise 나packaged_task 는비동기적으로실행을하기위해서는, 쓰레드를명시적으로
생성해서실행해야만했습니다. 하지만std::async 에어떤함수를전달한다면, 아예쓰레드를
알아서만들어서해당함수를비동기적으로실행하고, 그결과값을future 에전달합니다.


 #include <future>
 #include <iostream>
 #include <thread>
 #include <vector>

 // std::accumulate 와동일
 int sum(const std::vector<int>& v, int start, int end) {
   int total = 0;
   for (int i = start; i < end; ++i) {
     total += v[i];
   }
   return total;
 }

 int parallel_sum(const std::vector<int>& v) {
   // lower_half_future 는1 ~ 500 까지비동기적으로더함
   // 참고로람다함수를사용하면좀더깔끔하게표현할수도있다.
   // --> std::async([&v]() { return sum(v, 0, v.size() / 2); });
   std::future<int> lower_half_future =
     std::async(std::launch::async, sum, cref(v), 0, v.size() / 2);

   // upper_half 는501 부터1000 까지더함
   int upper_half = sum(v, v.size() / 2, v.size());

   return lower_half_future.get() + upper_half;
 }

 int main() {
   std::vector<int> v;
   v.reserve(1000);

   for (int i = 0; i < 1000; ++i) {
     v.push_back(i + 1);
   }

   std::cout << "1 부터1000 까지의합: " << parallel_sum(v) << std::endl;
 }



